-- Kartalar's new rules. Its tiers were cut for a catalog of 200 cards, and
-- when it grew to 500 the 301 added were all Common, 70% of the cards: now
-- the cards are tiered by rank among AniList's most loved in proportion,
-- 25 Mythic, 50 Legendary, 100 Epic, 150 Rare and 176 Common, each card's
-- attack, health and value its new rarity's, as internal/cards gives them.
-- A card is worth the diamonds an MLBB skin of the like tier costs: Mythic
-- 10 800 (Legend), Legendary 6 210 (Collector), Epic 899, Rare 599 (Elite)
-- and Common 269 (Basic).
-- A player opens 3 free cards a day, from midnight in Tashkent, not one an
-- hour: free_day is the day they last opened one and free_used how many
-- they opened that day. A copy of a card held adds no points, so every
-- player's points are counted again: each card they hold once, at its new
-- value.

ALTER TABLE card_players
    ADD COLUMN free_day  TIMESTAMPTZ,
    ADD COLUMN free_used INTEGER NOT NULL DEFAULT 0;

UPDATE card_catalog c
SET rarity = v.rarity, attack = v.attack, health = v.health, value = v.value, updated_at = now()
